#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

void cleanup_handler(void)
{
    fprintf(stderr, "[Handler] atexit handler executed.\n");
}

int main()
{
    pid_t pid;
    int status;

    // Register a cleanup handler
    if (atexit(cleanup_handler) != 0) {
        perror("atexit");
        return 1;
    }

    // Use printf, which buffers output to stdout
    printf("This output is buffered.\n");

    pid = fork();

    if (pid == -1) {
        perror("fork");
        return 1;
    } else if (pid == 0) {
        // CHILD PROCESS
        fprintf(stderr, "[Child] Terminating via _exit(2)...\n");
        // The buffered printf above will NOT be flushed.
        // The atexit handler will NOT be called.
        _exit(42);
    } else {
        // PARENT PROCESS
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            return 1;
        }

        if (WIFEXITED(status)) {
            fprintf(stderr, "[Parent] Child terminated with status: %d (0x%X)\n",
                    WEXITSTATUS(status), WEXITSTATUS(status));
        }

        // Note: If we used exit(3) here, the cleanup_handler would run.
        return 0;
    }
}
